import{af as a,z as t,J as s,ab as r}from"./chunks/framework.DKAZBqyW.js";const l=JSON.parse('{"title":"Creating a share","description":"","frontmatter":{},"headers":[],"relativePath":"apps/chasm/share/creating-a-share.md","filePath":"apps/chasm/share/creating-a-share.md"}'),o={name:"apps/chasm/share/creating-a-share.md"};function n(i,e,h,d,c,p){return t(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794232528000"},[...e[0]||(e[0]=[r('<h1 id="creating-a-share" tabindex="-1">Creating a share <a class="header-anchor" href="#creating-a-share" aria-label="Permalink to &quot;Creating a share&quot;">​</a></h1><h2 id="admin-portal" tabindex="-1">Admin portal <a class="header-anchor" href="#admin-portal" aria-label="Permalink to &quot;Admin portal&quot;">​</a></h2><p>Data can be shared from supported devices <a href="/docs/pr/39/apps/admin/devices/sharing">via the admin portal</a>. Open the device&#39;s <strong>More actions</strong> menu and choose <strong>Shared access</strong> under <strong>Connectivity</strong>. Check the device shown in the dialog, then choose the message type and time period to share.</p><p>The dialog defaults to <strong>Last 1 hour</strong> in your local timezone. Use <strong>Quick time range</strong> or edit the start and end times to select a period of up to <strong>24 hours</strong>. See <a href="/docs/pr/39/apps/admin/devices/sharing#time-selection">time selection</a> for UTC/local input and supported paste formats.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/11/screenshots/devices-share-e9133f54-4ec8-4685-82b8-f36315c36862.png" alt="Share device data dialog showing the selected device and time range" width="800" tabindex="0"><figcaption>Share device data dialog showing the selected device and time range</figcaption></figure><p>Click <strong>Share</strong>, then use <strong>Copy</strong> or <strong>Open share</strong>. Anyone with the link can view the shared data without signing in.</p><h2 id="message-headers" tabindex="-1">Message headers <a class="header-anchor" href="#message-headers" aria-label="Permalink to &quot;Message headers&quot;">​</a></h2><p>It is also possible to open up V3 messages to the share system by adding a custom header to the message when sending it to the chasm.</p><p>For more information on how to do this, please contact us.</p>',9)])])}const m=a(o,[["render",n]]);export{l as __pageData,m as default};
